type Task = { title: string; prompt: string; answer: string; explanation: string; options?: string[]; responseType?: 'integer' | 'text' | 'choice'; middleOutcome?: string; seniorOutcome?: string; levelRequirementId?: string; parts?: { expected: string; responseType: 'integer' | 'text' }[]; baseAnswer?: string };
const code = (language: string, lines: string[]) => `\n\n\`\`\`${language}\n${lines.join('\n')}\n\`\`\``;
const trace = 'Введите значения по порядку через |. Без кавычек и пояснений; пробелы по краям не учитываются.';
