  if (c === 0) return exact('Вложенная структура', trace + code('python', [`a = [[${n}], [2]]`, 'b = [row[:] for row in a]' + (flag ? '' : ' if False else a[:]'), `b[0].append(${n + 3})`, ...(middle ? ['b.append([9])'] : []), 'print(len(a[0]))', 'print(len(a))']), `${flag ? 1 : 2}|2`, 'Внешняя shallow-копия сохраняет ссылки на вложенные списки; копия каждой строки отделяет их.');
  if (c === 1 && s === 0) return exact('Полуоткрытая граница range', integer + code('python', [`values = range(${flag ? 0 : 1}, ${n}, ${middle ? 2 : 1})`, 'print(sum(values))']), Array.from({ length: n }, (_, i) => i).filter(i => i >= (flag ? 0 : 1) && (!middle || (i - (flag ? 0 : 1)) % 2 === 0)).reduce((a, b) => a + b, 0), 'Стоп range исключается; шаг применяется от начального значения.', 'integer');
  if (c === 1 && s === 1) return exact('Одноразовый итератор', trace + code('python', [`it = iter([${n}, ${n + 2}, ${n + 4}])`, ...(flag ? ['next(it)'] : []), 'print(sum(it))', ...(middle ? ['print(next(it, -1))'] : ['print(sum(it))'])]), `${flag ? 2 * n + 6 : 3 * n + 6}|${middle ? -1 : 0}`, 'Итератор потребляется; исчерпанный итератор не начинается заново.');
  if (c === 1) return exact('break и else цикла', trace + code('python', ['total = 0', `for x in [${n}, 2, ${flag ? -1 : 3}]:`, '    if x < 0:', '        break', `    total += x${middle ? ' * 2' : ''}`, 'else:', '    total += 10', 'print(total)']), (n + 2 + (flag ? 0 : 3)) * (middle ? 2 : 1) + (flag ? 0 : 10), 'else цикла выполняется только при завершении без break.', 'integer');
  if (c === 2 && s === 0) return exact('Аргумент по умолчанию', trace + code('python', [middle ? 'def add(x, items=None):' : 'def add(x, items=[]):', ...(middle ? ['    if items is None:', '        items = []'] : []), '    items.append(x)', '    return len(items)', `print(add(${n}))`, `print(add(${flag ? n + 1 : 0}))`]), `1|${middle ? 1 : 2}`, 'Изменяемое значение default создаётся один раз; None + создание списка отделяет вызовы.');
  if (c === 2 && s === 1) return exact('Замыкание и связанное значение', trace + code('python', [`functions = [${flag ? 'lambda i=i: i' : 'lambda: i'} for i in range(${n})]`, 'print(functions[0]())', ...(middle ? [`print(functions[${n - 1}]())`] : ['print(len(functions))'])]), `${flag ? 0 : n - 1}|${middle ? n - 1 : n}`, 'Замыкание без default читает i; default фиксирует значение в момент создания.');
  if (c === 2) return exact('Позиционные и именованные аргументы', integer + code('python', [`def total(a, b=${n}, *, scale=2):`, `    return (a ${flag ? '+' : '-'} b) * scale`, `print(total(${n + 4}, ${middle ? `b=${n - 1}, scale=3` : 'scale=1'}))`]), ((n + 4) + (flag ? 1 : -1) * (middle ? n - 1 : n)) * (middle ? 3 : 1), 'Именованные аргументы заменяют default; scale после * передаётся по имени.', 'integer');
  if (c === 3 && s === 0) return exact('finally после return', integer + code('python', ['def f():', '    try:', `        return ${n}`, '    finally:', ...(middle && flag ? [`        return ${n + 5}`] : ['        marker = 100']), 'print(f())']), middle && flag ? n + 5 : n, 'finally выполняется перед выходом. return в finally заменяет прежний результат.', 'integer');
