  if (c === 3) return exact('raise и повторная обработка', integer + code('python', [`total = ${n}`, 'try:', '    try:', `        total += ${flag ? 1 : 2}`, "        raise ValueError('bad')", '    except ValueError:', '        total += 3', ...(middle ? ['        raise'] : []), 'except ValueError:', '    total += 5', 'print(total)']), n + (flag ? 1 : 2) + 3 + (middle ? 5 : 0), 'Повторный raise передаёт исключение внешнему обработчику.', 'integer');
