  if (c === 5 && s === 0) return choice('Уникальный ключ', `Контракт: одно событие (tenant_id,event_id) обрабатывается один раз. ${flag ? 'event_id может совпадать у разных tenants.' : 'Система имеет одного tenant; event_id глобален.'} Какое ограничение выражает контракт?`, ['UNIQUE(tenant_id,event_id), обработка конфликта в той же транзакции с результатом.', 'UNIQUE(event_id), обработка конфликта в транзакции с результатом.', 'Только предварительный SELECT: два запроса никогда не выполнят его одновременно.', 'Проверка дубликатов только на клиенте.'], flag ? 0 : 1, 'Уникальность должна соответствовать области идентификатора; предварительная проверка не защищает от гонки.');
  if (c === 5 && s === 1) return choice('Ссылочная целостность', `Заказ с customer_id=${n} ${flag ? 'должен ссылаться на существующего клиента; удаление клиента при заказах запрещено' : 'может не иметь клиента, но ненулевой id должен существовать'}. Как задать поле?`, ['NOT NULL + FOREIGN KEY + ограничение удаления RESTRICT.', 'NULL допустим + FOREIGN KEY для непустого значения.', 'INTEGER без внешнего ключа и без проверки на сервере.', 'DEFAULT 0 независимо от наличия клиента id=0.'], flag ? 0 : 1, 'NOT NULL и FK решают разные задачи; FK требует существования только непустого значения.');
