  if (c === 1 && s === 0) return exact('Runtime-проверка unknown', trace + code('typescript', ['function read(v:unknown){', " if(typeof v!=='object'||v===null)return 'invalid';", ' const x=v as Record<string,unknown>;', " if(typeof x.count!=='number'" + (middle ? '||!Number.isInteger(x.count)||x.count<0' : '') + ")return 'invalid';", ' return String(x.count+1);}', `read({count:${n}})`, `read({count:${flag ? "'3'" : '-1'}})`]), `${n + 1}|${flag || middle ? 'invalid' : 0}`, 'as не валидирует внешний JSON; runtime проверяет тип, целочисленность и диапазон отдельно.');
