  if (c === 1) return choice('Доверие assertion', `JSON payload ${flag ? 'не проходит схему' : 'проходит схему, но пользователь не имеет прав на запись'}. Какой шаг необходим ${middle ? 'перед транзакцией' : 'на сервере'}?`, ['Отклонить невалидный payload и не выполнять запись.', 'Проверить авторизацию отдельно от схемы и отказать в записи.', 'as Payload достаточно, потому что типы сохраняются после компиляции.', 'Схема автоматически означает согласие другого пользователя.'], flag ? 0 : 1, 'Типы, валидация структуры и авторизация — независимые проверки.');
  if (c === 2 && s === 0) return exact('Generic сохраняет тип и порядок', trace + code('typescript', ['function first<T>(xs:readonly T[]):T|undefined{return xs[0]}', `String(first([${n},${n + 1}]))`, `String(first(${flag ? '[]' : `[${n + 2}]`}))`, ...(middle ? ["String(first(['a','b']))"] : [])]), `${n}|${flag ? 'undefined' : n + 2}${middle ? '|a' : ''}`, 'Generic не меняет runtime; пустой массив возвращает undefined по явному контракту.');
  if (c === 2 && s === 1) return choice('Ограничение generic', `Функция принимает T ${flag ? 'extends {id:number}' : 'без constraint'} и пытается читать item.id. strict:true. ${middle ? 'Поля остальных типов должны сохраняться в return T.' : ''} Какая правка соответствует контракту?`, ['Ограничение уже разрешает id; вернуть исходный T без стирания остальных полей.', 'Добавить extends {id:number}, если это требование функции; не использовать any.', 'Заменить все типы на any и считать проверку усиленной.', 'Вернуть number вместо T без изменения публичного контракта.'], flag ? 0 : 1, 'Constraint выражает требование id, сохраняя остальные свойства конкретного T.');
  if (c === 2) return exact('Функция высшего порядка', integer + code('typescript', ['function apply<T>(x:T,f:(v:T)=>number){return f(x)}', `apply(${n}, x=>x ${flag ? '+' : '*'} ${middle ? 3 : 2})`]), flag ? n + (middle ? 3 : 2) : n * (middle ? 3 : 2), 'Generic передаёт значение функции; результат определяет переданный callback.', 'integer');
  if (c === 3 && s === 0) return exact('Map и filter', integer + code('typescript', [`const xs=[${n},2,4];`, `xs.filter(x=>x ${flag ? '>' : '<='} 3).map(x=>x*${middle ? 3 : 2}).reduce((a,b)=>a+b,0)`]), (flag ? n + 4 : 2) * (middle ? 3 : 2), 'filter меняет состав, map преобразует каждый оставшийся элемент.', 'integer');
  if (c === 3 && s === 1) return exact('Object.entries', integer + code('typescript', [`const d={a:${n},b:2,c:0};`, `Object.entries(d).filter(([,v])=>v${flag ? '>0' : '>=0'}).length`]), flag ? 2 : 3, 'Нулевое значение включается при >=0 и исключается при >0.', 'integer');
  if (c === 3) return exact('Порядок сортировки', trace + code('typescript', [`const xs=[${n},2,10];`, `xs.sort(${flag ? '(a,b)=>a-b' : ''});`, 'String(xs[0])', `String(xs[${middle ? 1 : 2}])`]), flag ? `2|${middle ? Math.min(n, 10) : Math.max(n, 10)}` : `10|${middle ? 2 : n}`, 'Без comparator сравниваются строки; числовой comparator задаёт числовой порядок.');
  if (c === 4 && s === 0) return exact('Promise и порядок продолжений', trace + code('typescript', ["const log=['start'];", `Promise.resolve(${n}).then(x=>log.push(String(x)));`, `log.push('${flag ? 'sync' : 'now'}');`, '// После завершения текущего стека и очереди microtasks:', "log.join('|')"]), `start|${flag ? 'sync' : 'now'}|${n}`, 'then исполняется в microtask после синхронной части.');
  if (c === 4 && s === 1) return exact('catch и возвращённое значение', integer + code('typescript', [`const p=Promise.${flag ? `reject(new Error('bad'))` : `resolve(${n})`};`, `p.catch(()=>${middle ? 7 : 2}).then(x=>x+1);`, '// Какое число разрешит итоговый Promise?']), flag ? middle ? 8 : 3 : n + 1, 'catch преобразует rejection в resolved значение, последующий then применяет +1.', 'integer');
  if (c === 4) return choice('Ожидание async-операций', `Нужно сохранить ${n} независимых объектов. ${flag ? 'Одна ошибка должна отменить общий успешный ответ' : 'Нужно получить статус каждого независимо от ошибок'}. Как ожидать завершения ${middle ? 'и не выдавать успех до операций' : 'всех операций'}?`, ['await Promise.all(rows.map(save)); обработать отклонение общего результата.', 'await Promise.allSettled(rows.map(save)); разобрать каждое fulfilled/rejected.', 'rows.forEach(async row=>save(row)); сразу вернуть успех.', 'await rows.map(save); массив обещаний автоматически ожидается.'], flag ? 0 : 1, 'all и allSettled имеют разные контракты ошибки; forEach и await array не ожидают набор.');
  if (c === 5 && s === 0) return exact('Копия и изменение', trace + code('typescript', [`const a={count:${n},nested:{value:2}};`, `const b=${flag ? '{...a,nested:{...a.nested}}' : '{...a}'};`, 'b.nested.value=9;', ...(middle ? ['b.count+=3;'] : []), 'String(a.nested.value)', 'String(a.count)']), `${flag ? 2 : 9}|${n}`, 'Spread отделяет внешний объект, но вложенный требует собственной копии.');
  if (c === 5 && s === 1) return exact('Неизменяемое обновление по id', trace + code('typescript', [`const rows=[{id:1,v:${n}},{id:2,v:2}];`, `const next=rows.map(x=>x.id===${flag ? 1 : 2}?{...x,v:x.v+${middle ? 3 : 1}}:x);`, 'String(rows[0].v)', 'String(next[0].v)']), `${n}|${n + (flag ? middle ? 3 : 1 : 0)}`, 'map со spread изменяет только выбранный объект новой коллекции.');
  return choice('Readonly и runtime', `Объект объявлен readonly в TypeScript. ${flag ? 'Нужно предотвратить изменение во время исполнения' : 'Нужно получить новую версию без изменения исходной'}. Какой подход нужен?`, ['Явное runtime-замораживание нужных уровней или изоляция ссылок; readonly сам не замораживает.', 'Построить новое значение с копиями изменяемых уровней и сохранить исходную ссылку неизменной.', 'readonly автоматически вызывает Object.freeze для всего дерева.', 'as any гарантирует неизменяемость.'], flag ? 0 : 1, 'Readonly действует при проверке типов; runtime и глубокая неизменяемость требуют отдельного решения.');
