  if (c === 4) return choice('Область сбоя интерфейса', `Ошибка ${flag ? 'локальна для secondary-панели' : 'блокирует обязательную проверку прав перед действием'}. Как организовать состояние?`, ['Изолировать панель, оставить основную работу, показать retry без ложных данных.', 'Запретить зависимое действие до достоверного разрешения, показать ошибку и восстановление.', 'Всегда разрешить действие при любой ошибке авторизации.', 'Показать старые чужие данные как fallback.'], flag ? 0 : 1, 'Fallback не должен подменять права и факты; область блокировки соответствует зависимости.');
