  const middle = middleRequirementProbe(skillId, c, s, n, flag);
  const baseChoices = base.options?.map((text, original) => ({ text, original, order: hashNumber(`${skillId}|MiddleA|${c}|${s}|${n}|${flag}|${text}`) })).sort((a, b) => a.order - b.order);
